using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32;

[assembly: AssemblyTitle("Hot Corners")]
[assembly: AssemblyDescription("Simulador de Esquinas Activas para Windows 11")]
[assembly: AssemblyConfiguration("")]
[assembly: AssemblyCompany("Manuel Vrsalovic")]
[assembly: AssemblyProduct("Hot Corners")]
[assembly: AssemblyCopyright("Copyright © 2026")]
[assembly: AssemblyTrademark("")]
[assembly: AssemblyCulture("")]
[assembly: AssemblyVersion("1.6.0.0")]
[assembly: AssemblyFileVersion("1.6.0.0")]

class HotCornersApp
{
    [StructLayout(LayoutKind.Sequential)]
    public struct POINT
    {
        public int X;
        public int Y;
    }

    [DllImport("user32.dll")]
    static extern bool GetCursorPos(out POINT lpPoint);

    [DllImport("user32.dll")]
    public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);

    const byte VK_LWIN = 0x5B;
    const byte VK_TAB = 0x09;
    const uint KEYEVENTF_EXTENDEDKEY = 0x0001;
    const uint KEYEVENTF_KEYUP = 0x0002;

    private static NotifyIcon trayIcon;
    private static ContextMenu trayMenu;
    private static System.Windows.Forms.Timer monitorTimer;
    private static bool triggered = false;

    private const string IconoBase64 = "";


    [STAThread]
    static void Main(string[] args)
    {
        try
        {
            SetStartup(true);
        }
        catch (Exception ex)
        {
            LogToEventViewer(string.Format("Error en SetStartup: {0}", ex.Message));
        }

        trayMenu = new ContextMenu();
        trayMenu.MenuItems.Add("Salir de Hot Corners", OnExit);

        trayIcon = new NotifyIcon();
        trayIcon.Text = "Hot Corners v1.6";
        trayIcon.ContextMenu = trayMenu;

        try
        {
            byte[] iconBytes = Convert.FromBase64String(IconoBase64);
            using (MemoryStream ms = new MemoryStream(iconBytes))
            {
                trayIcon.Icon = new Icon(ms);
            }
        }
        catch (Exception ex)
        {
            trayIcon.Icon = SystemIcons.Information;
            LogToEventViewer(string.Format("Error al decodificar Base64: {0}", ex.Message));
        }

        trayIcon.Visible = true;

        monitorTimer = new System.Windows.Forms.Timer();
        monitorTimer.Interval = 50;
        monitorTimer.Tick += new EventHandler(MonitorTick);
        monitorTimer.Start();

        Application.Run();
    }

    private static void MonitorTick(object sender, EventArgs e)
    {
        try
        {
            POINT pos;
            if (GetCursorPos(out pos))
            {
                if (pos.X <= 5 && pos.Y <= 5)
                {
                    if (!triggered)
                    {
                        keybd_event(VK_LWIN, 0, KEYEVENTF_EXTENDEDKEY, UIntPtr.Zero);
                        keybd_event(VK_TAB, 0, KEYEVENTF_EXTENDEDKEY, UIntPtr.Zero);
                        keybd_event(VK_TAB, 0, KEYEVENTF_EXTENDEDKEY | KEYEVENTF_KEYUP, UIntPtr.Zero);
                        keybd_event(VK_LWIN, 0, KEYEVENTF_EXTENDEDKEY | KEYEVENTF_KEYUP, UIntPtr.Zero);

                        triggered = true;
                        
                        monitorTimer.Stop();
                        Thread.Sleep(800);
                        monitorTimer.Start();
                    }
                }
                else
                {
                    triggered = false;
                }
            }
        }
        catch (Exception ex)
        {
            LogToEventViewer(string.Format("Fallo critico en monitoreo: {0}", ex.Message));
        }
    }

    private static void OnExit(object sender, EventArgs e)
    {
        trayIcon.Visible = false;
        trayIcon.Dispose();
        Application.Exit();
    }

    static void SetStartup(bool startWithWindows)
    {
        string runKey = @"SOFTWARE\Microsoft\Windows\CurrentVersion\Run";
        using (RegistryKey key = Registry.CurrentUser.OpenSubKey(runKey, true))
        {
            if (startWithWindows)
            {
                key.SetValue("Hot Corners", string.Format("\"{0}\"", Application.ExecutablePath));
            }
            else
            {
                key.DeleteValue("Hot Corners", false);
            }
        }
    }

    static void LogToEventViewer(string errorMessage)
    {
        try
        {
            EventLog.WriteEntry("Application", "HotCorners Error: " + errorMessage, EventLogEntryType.Error);
        }
        catch { }
    }
}
